<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <meta http-equiv="X-UA-Compatible" content="ie=edge">
    @vite('resources/css/app.css')
    <title>Login</title>
</head>
<body class="flex h-screen bg-[#ffffff]">
    <section class="flex-1 w-200 bg-[#ffffff] flex flex-col items-center">
        <svg class="mt-8" width="130" height="161" viewBox="0 0 130 161" fill="none" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink">
            <rect width="130" height="161" fill="url(#pattern0_109_2947)"/>
            <defs>
            <pattern id="pattern0_109_2947" patternContentUnits="objectBoundingBox" width="1" height="1">
            <use xlink:href="#image0_109_2947" transform="matrix(0.00348432 0 0 0.00281343 0 -0.000789924)"/>
            </pattern>
            <image id="image0_109_2947" width="287" height="356" preserveAspectRatio="none" xlink:href="data:image/png;base64,"/>
            </defs>
        </svg>
        <div class="mt-13 w-115">
            <h2 class="text-4xl font-medium ">Login</h2>
            <p class="mt-3 text-[#606060]">Selamat Datang, harap masukkan username dan password anda.</p>
        </div>
        <div class="mx-auto w-115 mt-10">
            <form action="" class="space-y-5">
                <div>
                    <label for="username" class="mb-1 block text-sm font-medium text-gray-700">Username</label>
                    <input type="text" id="username" class="py-2 pl-2 block w-full rounded-md border border-gray-300 focus:border-primary-400 focus:ring focus:ring-primary-200 focus:ring-opacity-50 disabled:cursor-not-allowed disabled:bg-gray-50 disabled:text-gray-500" placeholder="Masukan Username..." required/>
                </div>
                <div>
                    <label for="password" class="mb-1 block text-sm font-medium text-gray-700">Password</label>
                    <input type="password" id="password" class="py-2 pl-2 block w-full rounded-md border border-gray-300 focus:border-primary-400 focus:ring focus:ring-primary-200 focus:ring-opacity-50 disabled:cursor-not-allowed disabled:bg-gray-50 disabled:text-gray-500" placeholder="Masukan Password..." required/>
                </div>
                <div class="flex items-center space-x-2">
                <input type="checkbox" id="example3" class="h-4 w-4 rounded border-gray-300 text-primary-600 shadow-sm focus:border-primary-300 focus:ring focus:ring-primary-200 focus:ring-opacity-50 focus:ring-offset-0 disabled:cursor-not-allowed disabled:text-gray-400" />
                <label for="example3" class="text-sm font-medium text-gray-700">Remember me</label>
                </div>
                <button type="submit" class=" mt-15 rounded-lg border border-blue-500 bg-blue-500 px-52 py-2.5 text-center text-sm font-medium text-white shadow-sm transition-all hover:border-blue-700 hover:bg-blue-700 focus:ring focus:ring-blue-200 disabled:cursor-not-allowed disabled:border-blue-300 disabled:bg-blue-300">Login</button>
            </form>
        </div>
    </section>
    <svg class="w-xl h-screen flex-2 mask-cover" viewBox="0 0 1080 785" fill="none" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink">
        <rect width="1080" height="785" fill="url(#pattern0_12_37)"/>
        <defs>
        <pattern id="pattern0_12_37" patternContentUnits="objectBoundingBox" width="1" height="1">
        <use xlink:href="#image0_12_37" transform="matrix(0.000367269 0 0 0.0005 -0.0509039 0)"/>
        </pattern>
            <image id="image0_12_37" width="3000" height="2000" preserveAspectRatio="none" xlink:href="data:image/jpeg;base64,"/>
        </defs>
    </svg>
</body>
</html>